fn enc_chat_progress(out: &mut ::std::vec::Vec<u8>, v: &ChatProgress, depth: i32) {
    let mut encoded_counter = CompactEncodedCounter::new(out.len());
    if let Some(oa_value) = v.done {
    if !(0..=9223372036854775807).contains(&oa_value) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    }
    if let Some(oa_value) = v.total {
    if !(0..=9223372036854775807).contains(&oa_value) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    }
    let n = v.unit.len();
    if n != 0 && !(1..=1048576).contains(&n) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    if v.unit.chars().any(char::is_control) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    out.push(b'{');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "phase");
    out.extend_from_slice(b": ");
    esc(out, &v.phase);
    encoded_counter.check(out, 1048576);
    if let Some(value) = &v.done {
        out.push(b',');
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "done");
        out.extend_from_slice(b": ");
        num(out, *value);
    }
    encoded_counter.check(out, 1048576);
    if let Some(value) = &v.total {
        out.push(b',');
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "total");
        out.extend_from_slice(b": ");
        num(out, *value);
    }
    encoded_counter.check(out, 1048576);
    if !v.unit.is_empty() {
        out.push(b',');
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "unit");
        out.extend_from_slice(b": ");
        esc(out, &v.unit);
    }
    encoded_counter.check(out, 1048576);
    out.push(b'\n');
    pad(out, depth);
    out.push(b'}');
    encoded_counter.check(out, 1048576);
}

fn enc_chat_usage(out: &mut ::std::vec::Vec<u8>, v: &ChatUsage, depth: i32) {
    if let Some(oa_value) = v.input {
    if !(0..=9223372036854775807).contains(&oa_value) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    }
    if let Some(oa_value) = v.output {
    if !(0..=9223372036854775807).contains(&oa_value) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    }
    if let Some(oa_value) = v.cache_read {
    if !(0..=9223372036854775807).contains(&oa_value) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    }
    if let Some(oa_value) = v.cache_write {
    if !(0..=9223372036854775807).contains(&oa_value) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    }
    if let Some(oa_value) = v.reasoning {
    if !(0..=9223372036854775807).contains(&oa_value) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    }
    out.push(b'{');
    let mut first = true;
    if let Some(value) = &v.input {
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "input");
        out.extend_from_slice(b": ");
        num(out, *value);
    }
    if let Some(value) = &v.output {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "output");
        out.extend_from_slice(b": ");
        num(out, *value);
    }
    if let Some(value) = &v.cache_read {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "cache_read");
        out.extend_from_slice(b": ");
        num(out, *value);
    }
    if let Some(value) = &v.cache_write {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "cache_write");
        out.extend_from_slice(b": ");
        num(out, *value);
    }
    if let Some(value) = &v.reasoning {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "reasoning");
        out.extend_from_slice(b": ");
        num(out, *value);
    }
    if !first {
        out.push(b'\n');
        pad(out, depth);
    }
    out.push(b'}');
}

