fn enc_chat_tool(out: &mut ::std::vec::Vec<u8>, v: &ChatTool, depth: i32) {
    let mut encoded_counter = CompactEncodedCounter::new(out.len());
    let n = v.name.len();
    if !(1..=64).contains(&n) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    if !v.name.bytes().all(|c| c.is_ascii_alphanumeric() || c == b'_' || c == b'.' || c == b'-') { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    let n = v.description.len();
    if n > 1048576 { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    let n = v.parameters.len();
    if !(1..=1048576).contains(&n) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    out.push(b'{');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "name");
    out.extend_from_slice(b": ");
    esc(out, &v.name);
    encoded_counter.check(out, 1048576);
    out.push(b',');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "description");
    out.extend_from_slice(b": ");
    esc(out, &v.description);
    encoded_counter.check(out, 1048576);
    out.push(b',');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "parameters");
    out.extend_from_slice(b": ");
    esc(out, &v.parameters);
    encoded_counter.check(out, 1048576);
    if let Some(value) = &v.strict {
        out.push(b',');
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "strict");
        out.extend_from_slice(b": ");
        out.extend_from_slice(if *value { b"true" } else { b"false" });
    }
    encoded_counter.check(out, 1048576);
    out.push(b'\n');
    pad(out, depth);
    out.push(b'}');
    encoded_counter.check(out, 1048576);
}

