fn enc_chat_history_read(out: &mut ::std::vec::Vec<u8>, v: &ChatHistoryRead, depth: i32) {
    let mut encoded_counter = CompactEncodedCounter::new(out.len());
    out.push(b'{');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "outcome");
    out.extend_from_slice(b": ");
    esc(out, v.outcome.as_str());
    encoded_counter.check(out, 1048576);
    if let Some(value) = &v.window {
        out.push(b',');
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "window");
        out.extend_from_slice(b": ");
        enc_oa_imported2(out, value, depth + 1);
    }
    encoded_counter.check(out, 1048576);
    if let Some(value) = &v.refusal {
        out.push(b',');
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "refusal");
        out.extend_from_slice(b": ");
        enc_oa_imported1(out, value, depth + 1);
    }
    encoded_counter.check(out, 1048576);
    out.push(b'\n');
    pad(out, depth);
    out.push(b'}');
    encoded_counter.check(out, 1048576);
}

