fn enc_request_entry(out: &mut ::std::vec::Vec<u8>, v: &RequestEntry, depth: i32) {
    let n = v.preferred_model.len();
    if n > 256 { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    let n = v.unavailable_hosts.len();
    if n > 64 { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    for oa_element in v.unavailable_hosts.iter() {
    let n = oa_element.len();
    if !(1..=4096).contains(&n) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    }
    let n = v.selection.len();
    if n > 64 { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    if v.selection.chars().any(char::is_control) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    out.push(b'{');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "entry");
    out.extend_from_slice(b": ");
    enc_audit_entry(out, &v.entry, depth + 1);
    if !v.preferred_model.is_empty() {
        out.push(b',');
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "preferred_model");
        out.extend_from_slice(b": ");
        esc(out, &v.preferred_model);
    }
    if !v.unavailable_hosts.is_empty() {
        out.push(b',');
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "unavailable_hosts");
        out.extend_from_slice(b": ");
        strs(out, &v.unavailable_hosts, depth + 1);
    }
    if !v.selection.is_empty() {
        out.push(b',');
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "selection");
        out.extend_from_slice(b": ");
        esc(out, &v.selection);
    }
    if let Some(value) = &v.placement {
        out.push(b',');
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "placement");
        out.extend_from_slice(b": ");
        esc(out, value);
    }
    out.push(b'\n');
    pad(out, depth);
    out.push(b'}');
}

