fn enc_program_budget(out: &mut ::std::vec::Vec<u8>, v: &ProgramBudget, depth: i32) {
    if !(0..=9223372036854775807).contains(&v.tokens_per_day) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    if !(0..=9223372036854775807).contains(&v.micros_per_day) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    if !(0..=9223372036854775807).contains(&v.requests_per_day) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    if !(0..=9223372036854775807).contains(&v.images_per_day) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    if !(0..=9223372036854775807).contains(&v.audio_seconds_per_day) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    if !(0..=9223372036854775807).contains(&v.characters_per_day) { std::panic::panic_any(Refusal{word:"bad_value",offset:0}); }
    out.push(b'{');
    let mut first = true;
    if v.tokens_per_day != 0 {
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "tokens_per_day");
        out.extend_from_slice(b": ");
        num(out, v.tokens_per_day);
    }
    if v.micros_per_day != 0 {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "micros_per_day");
        out.extend_from_slice(b": ");
        num(out, v.micros_per_day);
    }
    if v.requests_per_day != 0 {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "requests_per_day");
        out.extend_from_slice(b": ");
        num(out, v.requests_per_day);
    }
    if v.images_per_day != 0 {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "images_per_day");
        out.extend_from_slice(b": ");
        num(out, v.images_per_day);
    }
    if v.audio_seconds_per_day != 0 {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "audio_seconds_per_day");
        out.extend_from_slice(b": ");
        num(out, v.audio_seconds_per_day);
    }
    if v.characters_per_day != 0 {
        if !first {
            out.push(b',');
        }
        first = false;
        out.push(b'\n');
        pad(out, depth + 1);
        esc(out, "characters_per_day");
        out.extend_from_slice(b": ");
        num(out, v.characters_per_day);
    }
    if !first {
        out.push(b'\n');
        pad(out, depth);
    }
    out.push(b'}');
}

