    out.extend_from_slice(b": ");
    esc(out, &v.request);
    out.push(b',');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "cursor");
    out.extend_from_slice(b": ");
    num(out, v.cursor);
    out.push(b',');
    out.push(b'\n');
    pad(out, depth + 1);
    esc(out, "max_deltas");
    out.extend_from_slice(b": ");
    num(out, v.max_deltas);
