fn service_check_part(_v: &Part) -> ::std::result::Result<(), Refusal> {
    Ok(())
}

fn service_check_message(v: &Message) -> ::std::result::Result<(), Refusal> {
    for value in &v.parts {
        service_check_part(value)?;
    }
    Ok(())
}

fn service_check_tool(_v: &Tool) -> ::std::result::Result<(), Refusal> {
    Ok(())
}

fn service_check_temperature(_v: &Temperature) -> ::std::result::Result<(), Refusal> {
    Ok(())
}

fn service_check_options(v: &Options) -> ::std::result::Result<(), Refusal> {
    if let Some(value) = &v.temperature {
        service_check_temperature(value)?;
    }
    Ok(())
}

fn service_check_request(v: &Request) -> ::std::result::Result<(), Refusal> {
    for value in &v.messages {
        service_check_message(value)?;
    }
    for value in &v.tools {
        service_check_tool(value)?;
    }
    if let Some(value) = &v.options {
        service_check_options(value)?;
    }
    Ok(())
}

fn service_check_target(_v: &Target) -> ::std::result::Result<(), Refusal> {
    Ok(())
}

fn service_check_request_content(v: &RequestContent) -> ::std::result::Result<(), Refusal> {
    for value in &v.messages {
        service_check_message(value)?;
    }
    for value in &v.tools {
        service_check_tool(value)?;
    }
    if let Some(value) = &v.options {
        service_check_options(value)?;
    }
    Ok(())
}

fn service_check_request_v2(v: &RequestV2) -> ::std::result::Result<(), Refusal> {
    service_check_target(&v.target)?;
    service_check_request_content(&v.content)?;
    Ok(())
}

fn service_check_chat_tool_choice(v: &ChatToolChoice) -> ::std::result::Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0, limit: DEPTH_LIMIT };
    let n = v.name.len();
    if n != 0 && !(1..=64).contains(&n) { return r.refuse("bad_value"); }
    if !v.name.bytes().all(|c| c.is_ascii_alphanumeric() || c == b'_' || c == b'.' || c == b'-') { return r.refuse("bad_value"); }
    Ok(())
}

fn service_check_chat_tool(v: &ChatTool) -> ::std::result::Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0, limit: DEPTH_LIMIT };
    let n = v.name.len();
    if !(1..=64).contains(&n) { return r.refuse("bad_value"); }
    if !v.name.bytes().all(|c| c.is_ascii_alphanumeric() || c == b'_' || c == b'.' || c == b'-') { return r.refuse("bad_value"); }
    let n = v.description.len();
    if n > 1048576 { return r.refuse("bad_value"); }
    let n = v.parameters.len();
    if !(1..=1048576).contains(&n) { return r.refuse("bad_value"); }
    Ok(())
}

fn service_check_chat_reasoning(v: &ChatReasoning) -> ::std::result::Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0, limit: DEPTH_LIMIT };
    if let Some(oa_value) = v.budget {
    if !(1..=1048576).contains(&oa_value) { return r.refuse("bad_value"); }
    }
    Ok(())
}

fn service_check_chat_options(v: &ChatOptions) -> ::std::result::Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0, limit: DEPTH_LIMIT };
    if !(0..=9223372036854775807).contains(&v.max_output) { return r.refuse("bad_value"); }
    let n = v.stop.len();
    if n > 8 { return r.refuse("bad_value"); }
    for oa_element in v.stop.iter() {
    let n = oa_element.len();
    if n > 1048576 { return r.refuse("bad_value"); }
    }
    let n = v.json_schema.len();
    if n != 0 && !(1..=1048576).contains(&n) { return r.refuse("bad_value"); }
    if let Some(value) = &v.temperature {
        service_check_temperature(value)?;
    }
    if let Some(value) = &v.tool_choice {
        service_check_chat_tool_choice(value)?;
    }
    if let Some(value) = &v.reasoning {
        service_check_chat_reasoning(value)?;
    }
    Ok(())
}

fn service_check_reasoning_seal(v: &ReasoningSeal) -> ::std::result::Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0, limit: DEPTH_LIMIT };
    let n = v.origin.len();
    if !(1..=256).contains(&n) { return r.refuse("bad_value"); }
    if v.origin.chars().any(char::is_control) { return r.refuse("bad_value"); }
    let n = v.bytes.len();
    if n > 524288 { return r.refuse("bad_value"); }
    Ok(())
}

fn service_check_chat_input_part(v: &ChatInputPart) -> ::std::result::Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0, limit: DEPTH_LIMIT };
    let n = v.text.len();
    if n > 1048576 { return r.refuse("bad_value"); }
    let n = v.digest.len();
    if n != 0 && !(71..=135).contains(&n) { return r.refuse("bad_value"); }
    let n = v.media_type.len();
    if n != 0 && !(1..=10).contains(&n) { return r.refuse("bad_value"); }
    let n = v.call_id.len();
    if n != 0 && !(1..=1048576).contains(&n) { return r.refuse("bad_value"); }
    let n = v.name.len();
    if n != 0 && !(1..=64).contains(&n) { return r.refuse("bad_value"); }
    if !v.name.bytes().all(|c| c.is_ascii_alphanumeric() || c == b'_' || c == b'.' || c == b'-') { return r.refuse("bad_value"); }
    let n = v.arguments.len();
    if n > 1048576 { return r.refuse("bad_value"); }
    Ok(())
}

