fn service_check_chat_content(v: &ChatContent) -> ::std::result::Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0, limit: DEPTH_LIMIT };
    let n = v.messages.len();
    if !(1..=512).contains(&n) { return r.refuse("bad_value"); }
    let n = v.tools.len();
    if n > 128 { return r.refuse("bad_value"); }
    let n = v.extensions.len();
    if n > 1048576 { return r.refuse("bad_value"); }
    for oa_element in v.extensions.keys() {
    let n = oa_element.len();
    if !(1..=128).contains(&n) { return r.refuse("bad_value"); }
    }
    for oa_element in v.extensions.values() {
    let n = oa_element.len();
    if n > 1048576 { return r.refuse("bad_value"); }
    }
    let n = v.required_extensions.len();
    if n > 1048576 { return r.refuse("bad_value"); }
    for oa_element in v.required_extensions.iter() {
    let n = oa_element.len();
    if !(1..=128).contains(&n) { return r.refuse("bad_value"); }
    }
    let n = v.guarantees.len();
    if n > 4 { return r.refuse("bad_value"); }
    let n = v.credential.len();
    if n != 0 && !(1..=64).contains(&n) { return r.refuse("bad_value"); }
    if !v.credential.bytes().all(|c| c.is_ascii_alphanumeric() || c == b'_' || c == b'.' || c == b'-') { return r.refuse("bad_value"); }
    for value in &v.messages {
        service_check_chat_message(value)?;
    }
    for value in &v.tools {
        service_check_chat_tool(value)?;
    }
    if let Some(value) = &v.options {
        service_check_chat_options(value)?;
    }
    Ok(())
}

